export function initCreatorFlow({onPreview}={}){
 const root=document.querySelector('.customizer');
 const steps=[
  {label:'Para quem',next:'fotos',hint:'Escolha o tipo de presente, a ocasião e o nome de quem vai receber. No convite, preencha também a data e o local.',selectors:['.format-field','#occasion-select','#wedding-path','#recipient','.experience-identity','#invite-fields']},
  {label:'Fotos',next:'mensagem',hint:'Toque em “Escolher fotos” para buscar no aparelho. Escolha a foto da capa. Se for um livro, você também pode acrescentar páginas.',selectors:['.photo-upload','#upload-status','.memory-photos','.memory-pages']},
  {label:'Mensagem e áudio',next:'extras',hint:'Escreva sua mensagem. Se quiser, acrescente uma carta, uma música ou uma gravação de voz. O som é opcional.',selectors:['#message','.audio-studio','.letter-editor']},
  {label:'Extras',next:'capa',hint:'Esta etapa é opcional. Acrescente uma surpresa, prepare convidados ou siga direto para a capa.',selectors:['.extras-editor','.guest-manager','.reply-inbox']},
  {label:'Capa e cores',next:'conferir',hint:'A capa escolhida já está pronta para usar. Mude a cor principal ou abra as opções abaixo para ajustar mais detalhes.',selectors:['.book-finish-editor','.appearance-editor','.stationery-editor','.story-design-editor','.character-field','.cover-field','.materials-panel','.qr-panel']},
  {label:'Conferir e entregar',hint:'Abra a prévia para ver como a pessoa recebe. Depois, publique para criar o link ou baixe o arquivo do presente.',selectors:['.story-export-panel','.digital-delivery','.cloud-delivery','.delivery-tools','#recipient-preview','.review-keepsake','.library-controls','.draft-status']}
 ];
 root.querySelector('.atelier-steps').hidden=true;
 const nav=document.createElement('nav');nav.className='creator-flow-tabs';nav.setAttribute('aria-label','Etapas para criar seu presente');
 const heading=document.createElement('h3');heading.className='creator-flow-heading';heading.id='creator-flow-heading';heading.tabIndex=-1;
 const hint=document.createElement('p');hint.className='creator-flow-hint';hint.id='creator-flow-hint';
 const quick=document.createElement('div');quick.className='creator-format-switch';quick.setAttribute('role','group');quick.setAttribute('aria-label','Mudar o tipo de presente');
 for(const [key,label]of[['stories','Stories'],['livro','Livro com páginas'],['cartao','Cartão simples'],['convite','Convite']]){const button=document.createElement('button');button.type='button';button.className='quick-format';button.dataset.quickFormat=key;button.textContent=label;button.addEventListener('click',()=>{document.querySelector('.format[data-format='+key+']').click();updateReview();});quick.append(button);}
 const preview=document.createElement('button');preview.type='button';preview.className='creator-live-preview';preview.textContent='Ver como a pessoa recebe ↗';
 const previewStatus=document.createElement('p');previewStatus.className='creator-preview-status';previewStatus.setAttribute('role','status');
 root.prepend(nav,quick,heading,hint,preview,previewStatus);
 let active=0;const panels=[];
 steps.forEach((step,index)=>{const section=document.createElement('section');section.className='creator-flow-panel';section.id='creator-step-'+index;section.setAttribute('aria-label',step.label);for(const selector of step.selectors){let element=root.querySelector(selector);if(element?.matches('input,textarea,select'))element=element.closest('.field');if(element)section.append(element);}
  if(index===2)for(const optional of section.querySelectorAll('.audio-studio,.letter-editor'))optional.open=false;
  if(index===4)for(const element of[...section.children]){if(element.classList.contains('cover-field'))continue;if(element.tagName==='DETAILS'){element.open=false;continue;}const fold=document.createElement('details');fold.className='creator-option-fold';const summary=document.createElement('summary');summary.textContent=element.querySelector('h3,legend')?.textContent||({'qr-panel':'Cartão com QR','materials-panel':'Texturas e acabamentos'})[element.className]||'Mais detalhes';fold.append(summary);element.before(fold);fold.append(element);}
  root.append(section);panels.push(section);const button=document.createElement('button');button.type='button';button.textContent=(index+1)+' '+step.label;button.setAttribute('aria-controls',section.id);button.addEventListener('click',()=>show(index,true,true));nav.append(button);
 });
 const review=document.createElement('section');review.className='creator-review-summary';review.setAttribute('aria-labelledby','creator-review-title');review.innerHTML='<h4 id="creator-review-title">Uma última olhada.</h4><p>Confira o que você colocou. Ainda dá para voltar e mudar.</p><dl></dl>';panels[5].prepend(review);
 function updateReview(){const list=review.querySelector('dl'),format=document.querySelector('.quick-format[aria-pressed=true]')?.dataset.quickFormat||document.querySelector('.format.selected')?.dataset.format||'stories',recipient=document.querySelector('#recipient').value.trim(),photos=root.querySelectorAll('.photo-library-item').length,message=document.querySelector('#message').value.trim(),letter=document.querySelector('#personal-letter')?.value.trim()||'',rows=[['Para',recipient||'Nome ainda não preenchido',0,'#recipient'],['Fotos',photos?photos+(photos===1?' foto adicionada':' fotos adicionadas'):'Sem fotos. Você pode adicionar se quiser.',1,'.photo-upload'],['Mensagem principal',message?'Sua mensagem principal está escrita.':'Sem mensagem principal. Você pode acrescentar se quiser.',2,'#message'],['Carta',letter?'Sua carta está escrita.':'Sem carta. É opcional.',2,'#personal-letter']];
  if(format==='convite')rows.push(['Data',document.querySelector('#event-date').value?new Date(document.querySelector('#event-date').value+'T12:00:00').toLocaleDateString('pt-BR'):'Data ainda não informada',0,'#event-date'],['Local',document.querySelector('#event-place').value.trim()||'Local ainda não informado',0,'#event-place']);
  list.replaceChildren();for(const[label,text,step,selector]of rows){const group=document.createElement('div'),term=document.createElement('dt'),description=document.createElement('dd'),button=document.createElement('button');term.textContent=label;description.textContent=text;button.type='button';button.textContent='Editar';button.setAttribute('aria-label','Editar '+label.toLocaleLowerCase('pt-BR'));button.addEventListener('click',()=>{show(step,true,true);const target=document.querySelector(selector);for(let parent=target?.parentElement;parent&&parent!==root;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;if(target?.matches('input,textarea,select')){target.scrollIntoView({behavior:'instant',block:'center'});target.focus({preventScroll:true});}});group.append(term,description,button);list.append(group);}
 }
 const photoLibrary=root.querySelector('.photo-library');if(photoLibrary){const observer=new MutationObserver(()=>{if(active===5)updateReview();});observer.observe(photoLibrary,{childList:true});addEventListener('pagehide',()=>observer.disconnect(),{once:true});}
 const controls=document.createElement('div');controls.className='creator-flow-controls';controls.innerHTML='<button type="button" class="creator-back">← Voltar</button><span role="status" aria-live="polite"></span><button type="button" class="creator-next">Continuar →</button>';root.append(controls);
 function show(index,scroll=true,focus=false){active=Math.max(0,Math.min(steps.length-1,index));panels.forEach((panel,i)=>panel.hidden=i!==active);[...nav.children].forEach((button,i)=>{if(i===active)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current');button.classList.toggle('current',i===active);});heading.textContent=steps[active].label;hint.textContent=steps[active].hint;quick.hidden=active===0;controls.querySelector('.creator-back').disabled=active===0;controls.querySelector('.creator-next').hidden=active===steps.length-1;controls.querySelector('.creator-next').textContent='Ir para '+(steps[active].next||'conferir')+' →';controls.querySelector('[role=status]').textContent='Etapa '+(active+1)+' de '+steps.length;updateReview();if(scroll)root.scrollIntoView({behavior:'instant',block:'start'});if(focus)heading.focus({preventScroll:true});}
 controls.querySelector('.creator-back').addEventListener('click',()=>show(active-1,true,true));controls.querySelector('.creator-next').addEventListener('click',()=>show(active+1,true,true));
 preview.addEventListener('click',async()=>{preview.disabled=true;preview.setAttribute('aria-busy','true');previewStatus.textContent='Preparando a prévia…';try{if(onPreview)await onPreview();else document.querySelector('#recipient-preview')?.click();updateReview();previewStatus.textContent='Você pode fechar a prévia e continuar de onde parou.';}catch{previewStatus.textContent='Não foi possível abrir a prévia agora. Seu rascunho continua aqui.';}finally{preview.disabled=false;preview.setAttribute('aria-busy','false');}});
 root.addEventListener('input',()=>{if(active===5)updateReview();});root.addEventListener('change',()=>{if(active===5)updateReview();});
 document.addEventListener('creator:reveal',event=>{const element=document.querySelector(event.detail);const index=panels.findIndex(panel=>panel.contains(element));if(index>=0){show(index,false);for(let parent=element?.parentElement;parent&&parent!==root;parent=parent.parentElement)if(parent.tagName==='DETAILS')parent.open=true;}});
 show(0,false);return{show};
}
